# Native Russian landing pages for India-Russia freight. Base chrome: ru/cbm-calculator.html
import re, json, html, io, sys
R = '/home/claude/yamlogistics-website/'
e = lambda x: html.escape(str(x), quote=True)
BASE = io.open(R + 'ru/cbm-calculator.html', encoding='utf-8').read()
HEAD = BASE[:BASE.index('<main id="app">')]
TAIL = BASE[BASE.index('</main>'):]
TAIL = re.sub(r'<script src="yam-runtime\.js"></script>\s*<script>.*?</script>', '', TAIL, flags=re.S)
TAIL = re.sub(r'<script src="(yam-print|ck-disclaimer|ck-clear)\.js[^"]*" defer></script>', '', TAIL)
H2 = "font-family:'Archivo',sans-serif;font-weight:900;font-stretch:110%;font-size:clamp(30px,3.6vw,44px);line-height:1.04;letter-spacing:-0.03em;margin:0 0 20px"
H3 = "font-family:'Archivo',sans-serif;font-weight:800;font-size:22px;margin:26px 0 8px"
P = "font-size:17px;line-height:1.7;color:#3D5873;margin:0 0 14px;max-width:820px"
def p(t): return '<p style="%s">%s</p>' % (P, t)
def h3(t): return '<h3 style="%s">%s</h3>' % (H3, t)
def ul(items): return '<ul style="%s;padding-left:22px">%s</ul>' % (P, ''.join('<li style="margin-bottom:8px">%s</li>' % i for i in items))
def table(head, rows):
    th = ''.join('<th style="text-align:left;padding:12px;font-family:\'Geist Mono\',monospace;font-size:12px;color:#17436B;background:#EAF4FD">%s</th>' % e(h) for h in head)
    tr = ''.join('<tr>%s</tr>' % ''.join('<td style="padding:12px;border-top:1px solid #E1EDF7;font-size:15px;line-height:1.5;color:#3D5873;vertical-align:top">%s</td>' % c for c in r) for r in rows)
    return '<div style="overflow-x:auto;margin:8px 0 18px"><table style="border-collapse:collapse;width:100%%;max-width:900px;background:#fff;border-radius:14px"><tr>%s</tr>%s</table></div>' % (th, tr)
def note(t): return '<div style="background:#FFF8E6;border-radius:20px;padding:18px 22px;font-size:15px;line-height:1.6;color:#4A3B10;max-width:860px;margin:18px 0">%s</div>' % t
def cards(items):
    return '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin:12px 0 8px">' + ''.join('<a href="%s" style="display:block;background:#fff;border-radius:18px;padding:16px 18px;text-decoration:none;color:#0B2A4A;box-shadow:0 0 0 1px #E1EDF7"><b style="font-family:\'Archivo\',sans-serif;font-size:16px;display:block">%s</b><span style="font-size:14px;line-height:1.45;color:#3D5873;display:block;margin-top:4px">%s</span></a>' % (h, e(t), e(d)) for h, t, d in items) + '</div>'
def btn(h, t, alt=False):
    st = 'background:#FFC93C;color:#0B2A4A' if not alt else 'background:#fff;color:#0A6CC2;box-shadow:inset 0 0 0 2px #0A6CC2'
    return '<a href="%s" style="display:inline-block;%s;border-radius:999px;padding:14px 26px;font-family:\'Archivo\',sans-serif;font-weight:800;font-size:16px;text-decoration:none;margin:6px 10px 6px 0">%s</a>' % (h, st, e(t))
def sect(inner, bg='#FFFFFF'): return '<div style="background:%s"><div style="max-width:1000px;margin:0 auto;padding:56px 32px">%s</div></div>' % (bg, inner)
SIDE = 'Мы занимаемся логистикой и таможенным оформлением на стороне Индии. Условия оплаты, санкционные и иные ограничения стороны сделки проверяют самостоятельно до отгрузки.'
CONTACT = note('<b>Запросите ставку.</b> Пришлите наименование товара, вес и объём, порт отправления и пункт назначения — мы вернёмся с маршрутом и сроками. <a href="ru/contact" style="color:#0A6CC2;font-weight:700">Связаться с нами</a>. YAM Logistics — лицензированный таможенный брокер (лицензия R-7/92) и экспедитор, Нью-Дели.')
REL = [('ru/dostavka-gruzov-iz-indii-v-rossiyu', 'Доставка грузов из Индии в Россию', 'Морем, авиа и мультимодально: порты, сроки, документы.'),
       ('ru/dostavka-iz-indii-novorossiysk', 'Из Индии в Новороссийск', 'Контейнеры из Мундры и Нхава-Шевы.'),
       ('ru/dostavka-iz-indii-sankt-peterburg', 'Из Индии в Санкт-Петербург', 'Северо-запад России и Москва.'),
       ('ru/dostavka-iz-indii-vladivostok', 'Из Индии во Владивосток', 'Коридор Ченнаи — Владивосток.'),
       ('ru/tamozhennoe-oformlenie-eksporta-v-indii', 'Экспорт из Индии: таможня', 'Оформление отправки в Индии для покупателей из России.'),
       ('ru/cbm-calculator', 'Калькулятор CBM', 'Объём и оплачиваемый вес груза.')]
PAGES = []
def S(slug, T, DESC, crumb, chip, h1, intro, secs, faq, rel):
    PAGES.append(dict(slug=slug, T=T, DESC=DESC, crumb=crumb, chip=chip, h1=h1, intro=intro, secs=secs, faq=faq, rel=rel))

