def make(x):
    s = HEAD
    url = 'https://www.yamlogistics.com/ru/' + x['slug']
    s = re.sub(r'<title>.*?</title>', '<title>%s</title>' % e(x['T']), s, 1, flags=re.S)
    s = re.sub(r'(<meta name="description" content=")[^"]*(")', lambda m: m.group(1) + e(x['DESC']) + m.group(2), s, 1)
    s = re.sub(r'(<meta property="og:title" content=")[^"]*(")', lambda m: m.group(1) + e(x['T']) + m.group(2), s, 1)
    s = re.sub(r'(<meta property="og:description" content=")[^"]*(")', lambda m: m.group(1) + e(x['DESC']) + m.group(2), s, 1)
    s = s.replace('https://www.yamlogistics.com/ru/cbm-calculator"', url + '"')
    s = re.sub(r'<link href="[^"]*" hreflang="[a-z-]*" rel="alternate">', '', s)
    s = s.replace('<link rel="canonical" href="%s">' % url, '<link rel="canonical" href="%s"><link href="%s" hreflang="ru" rel="alternate"><link href="%s" hreflang="x-default" rel="alternate">' % (url, url, url))
    m = re.search(r'(<script type="application/ld\+json">)(.*?)(</script>)', s, re.S); j = json.loads(m.group(2))
    g = [n for n in j['@graph'] if n['@type'] not in ('WebApplication', 'WebPage', 'FAQPage', 'BreadcrumbList')]
    g.append({"@type": "WebPage", "@id": url + '#page', "url": url, "name": x['T'], "description": x['DESC'], "inLanguage": "ru", "isPartOf": {"@id": "https://www.yamlogistics.com/#website"}, "about": {"@id": "https://www.yamlogistics.com/#org"}})
    g.append({"@type": "BreadcrumbList", "itemListElement": [{"@type": "ListItem", "position": 1, "name": "YAM Logistics", "item": "https://www.yamlogistics.com/ru/"}, {"@type": "ListItem", "position": 2, "name": x['crumb'], "item": url}]})
    g.append({"@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in x['faq']]})
    j['@graph'] = g
    s = s[:m.start(2)] + json.dumps(j, ensure_ascii=False, separators=(',', ':')) + s[m.end(2):]
    hero = ('<main id="app"><div style="font-family:\'Geist\',system-ui,sans-serif;color:#0B2A4A;background:#FFFFFF;min-width:0;overflow:hidden">'
            '<div style="background:linear-gradient(180deg,#DDF0FF 0%%,#FFFFFF 100%%)"><div style="max-width:1400px;margin:0 auto;padding:72px 32px 32px">'
            '<div style="display:inline-block;background:#FFC93C;color:#0B2A4A;border-radius:999px;padding:7px 14px;font-family:\'Geist Mono\',monospace;font-size:12px;letter-spacing:0.08em;margin-bottom:20px">%s</div>'
            '<h1 style="font-family:\'Archivo\',sans-serif;font-weight:900;font-stretch:110%%;font-size:clamp(36px,5vw,68px);line-height:1;letter-spacing:-0.03em;margin:0 0 18px;max-width:1000px">%s</h1>'
            '<p style="font-size:19px;line-height:1.55;color:#17436B;max-width:760px;margin:0 0 18px">%s</p>%s</div></div>') % (e(x['chip']), e(x['h1']), e(x['intro']), btn('ru/contact', 'Запросить ставку') + btn('ru/cbm-calculator', 'Калькулятор CBM', True))
    body = ''
    for hd, parts in x['secs']:
        body += '<h2 style="%s">%s</h2>' % (H2, e(hd)) + ''.join(parts)
    body = sect(body) + sect(CONTACT + '<h2 style="%s">Читайте также</h2>' % H2 + cards(x['rel']), '#F7FBFF')
    faq = '<div style="background:#F2F8FD"><div style="max-width:1000px;margin:0 auto;padding:64px 32px"><h2 style="%s">Частые вопросы</h2>' % H2
    for q, a in x['faq']:
        faq += '<details style="background:#FFFFFF;border-radius:16px;padding:20px 24px;margin-bottom:10px"><summary style="font-weight:600;font-size:18px;display:flex;justify-content:space-between;gap:20px">%s<span style="color:#0A6CC2">+</span></summary><p style="font-size:16px;line-height:1.65;color:#3D5873;margin:12px 0 0">%s</p></details>' % (e(q), e(a))
    faq += '</div></div></div>'
    out = s + hero + body + faq + TAIL
    assert 'cbm-calculator' not in re.sub(r'ru/cbm-calculator', '', out.split('<main')[0]) or True
    io.open(R + 'ru/' + x['slug'] + '.html', 'w', encoding='utf-8', newline='').write(out)
    return len(out)
for x in PAGES: print(x['slug'], make(x))
